INSERT OR IGNORE INTO Topic (id,categoryId,title,description,"order",published) SELECT 'dea-biblio-group-1', 'cmv3voewj000dv1igg3ey1n7c', 'Dasar Analisis Bibliometrik', 'Bab 01–03', 1, 1 FROM Category WHERE id='cmv3voewj000dv1igg3ey1n7c';
INSERT OR IGNORE INTO Quiz (id,topicId,title,passingScore,published,isFree) SELECT 'dea-biblio-quiz-1', 'dea-biblio-group-1', 'Kuis 1. Dasar Analisis Bibliometrik', 70, 1, 1 FROM Topic WHERE id='dea-biblio-group-1';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-1-q1', 'dea-biblio-quiz-1', 'Manakah yang paling tepat menggambarkan analisis bibliometrik?', 'Analisis bibliometrik mengolah metadata terbitan seperti penulis, afiliasi, jurnal, tahun, kata kunci, dan rujukan secara kuantitatif. Menggabungkan hasil uji acak adalah meta-analisis. Menilai risiko bias adalah ciri telaah sistematik. Memilih sumber menurut pengalaman adalah ciri tinjauan naratif.', 1 FROM Quiz WHERE id='dea-biblio-quiz-1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q1-o1', 'dea-biblio-quiz-1-q1', 'Metode kuantitatif yang mengolah metadata terbitan ilmiah untuk mengukur produktivitas dan dampak serta memetakan struktur suatu bidang', 1, 1 FROM Question WHERE id='dea-biblio-quiz-1-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q1-o2', 'dea-biblio-quiz-1-q1', 'Telaah yang menggabungkan hasil beberapa uji acak menjadi satu angka efek', 0, 2 FROM Question WHERE id='dea-biblio-quiz-1-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q1-o3', 'dea-biblio-quiz-1-q1', 'Tinjauan pustaka yang sumbernya dipilih menurut pengalaman penulis', 0, 3 FROM Question WHERE id='dea-biblio-quiz-1-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q1-o4', 'dea-biblio-quiz-1-q1', 'Telaah yang menilai risiko bias setiap studi sebelum menarik simpulan', 0, 4 FROM Question WHERE id='dea-biblio-quiz-1-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q1-o5', 'dea-biblio-quiz-1-q1', 'Survei pendapat para ahli tentang arah penelitian suatu bidang', 0, 5 FROM Question WHERE id='dea-biblio-quiz-1-q1';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-1-q2', 'dea-biblio-quiz-1', 'Siapakah yang memperkenalkan istilah bibliometrics pada 1969?', 'Pritchard memperkenalkan istilah bibliometrics pada 1969 dan mendefinisikannya sebagai penerapan metode matematika dan statistika pada buku dan media komunikasi lain. Hirsch mengusulkan indeks h pada 2005. Lotka dan Bradford dikenal melalui hukum yang memakai nama mereka.', 2 FROM Quiz WHERE id='dea-biblio-quiz-1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q2-o1', 'dea-biblio-quiz-1-q2', 'Eugene Garfield', 0, 1 FROM Question WHERE id='dea-biblio-quiz-1-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q2-o2', 'dea-biblio-quiz-1-q2', 'Alan Pritchard', 1, 2 FROM Question WHERE id='dea-biblio-quiz-1-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q2-o3', 'dea-biblio-quiz-1-q2', 'Jorge Hirsch', 0, 3 FROM Question WHERE id='dea-biblio-quiz-1-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q2-o4', 'dea-biblio-quiz-1-q2', 'Alfred Lotka', 0, 4 FROM Question WHERE id='dea-biblio-quiz-1-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q2-o5', 'dea-biblio-quiz-1-q2', 'Samuel Bradford', 0, 5 FROM Question WHERE id='dea-biblio-quiz-1-q2';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-1-q3', 'dea-biblio-quiz-1', 'Unit yang diolah dalam analisis bibliometrik adalah', 'Analisis bibliometrik tidak membaca isi temuan tiap artikel. Yang diolah adalah data tentang terbitan itu, yaitu judul, penulis, afiliasi, jurnal, tahun, kata kunci, dan daftar rujukan. Karena itu metode ini tidak menilai mutu studi dan tidak menyimpulkan efek terapi.', 3 FROM Quiz WHERE id='dea-biblio-quiz-1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q3-o1', 'dea-biblio-quiz-1-q3', 'Angka efek dari tiap studi', 0, 1 FROM Question WHERE id='dea-biblio-quiz-1-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q3-o2', 'dea-biblio-quiz-1-q3', 'Data pasien pada tiap studi', 0, 2 FROM Question WHERE id='dea-biblio-quiz-1-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q3-o3', 'dea-biblio-quiz-1-q3', 'Metadata terbitan', 1, 3 FROM Question WHERE id='dea-biblio-quiz-1-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q3-o4', 'dea-biblio-quiz-1-q3', 'Skor risiko bias tiap studi', 0, 4 FROM Question WHERE id='dea-biblio-quiz-1-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q3-o5', 'dea-biblio-quiz-1-q3', 'Transkrip wawancara peneliti', 0, 5 FROM Question WHERE id='dea-biblio-quiz-1-q3';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-1-q4', 'dea-biblio-quiz-1', 'Seorang residen ingin mengetahui apakah suatu obat menurunkan angka kematian pada gagal jantung. Jenis telaah yang paling sesuai adalah', 'Pertanyaan tentang efek suatu terapi dijawab dengan telaah sistematik dan bila studinya serupa dengan meta-analisis. Analisis bibliometrik tidak menilai mutu studi dan tidak menghitung efek sehingga tidak dapat memberi simpulan tentang manfaat terapi.', 4 FROM Quiz WHERE id='dea-biblio-quiz-1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q4-o1', 'dea-biblio-quiz-1-q4', 'Analisis bibliometrik', 0, 1 FROM Question WHERE id='dea-biblio-quiz-1-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q4-o2', 'dea-biblio-quiz-1-q4', 'Analisis ko-kata', 0, 2 FROM Question WHERE id='dea-biblio-quiz-1-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q4-o3', 'dea-biblio-quiz-1-q4', 'Analisis ko-kepengarangan', 0, 3 FROM Question WHERE id='dea-biblio-quiz-1-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q4-o4', 'dea-biblio-quiz-1-q4', 'Telaah sistematik dengan meta-analisis bila datanya dapat digabung', 1, 4 FROM Question WHERE id='dea-biblio-quiz-1-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q4-o5', 'dea-biblio-quiz-1-q4', 'Analisis seratus artikel yang paling banyak disitasi', 0, 5 FROM Question WHERE id='dea-biblio-quiz-1-q4';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-1-q5', 'dea-biblio-quiz-1', 'Donthu dkk. memberi contoh jumlah terbitan yang membuat suatu bidang cukup besar untuk dianalisis secara bibliometrik. Jumlah itu adalah sedikitnya', 'Donthu dkk. menulis bahwa bidang dengan ratusan terbitan dalam jumlah besar, misalnya 500 atau lebih, atau ribuan terbitan cukup besar untuk dianalisis secara bibliometrik. Bidang dengan puluhan atau 100 sampai 300 terbitan belum cukup. Ketersediaan pustaka bergantung pada bidangnya sehingga angka itu merupakan patokan awal dan bukan aturan mutlak.', 5 FROM Quiz WHERE id='dea-biblio-quiz-1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q5-o1', 'dea-biblio-quiz-1-q5', '50', 0, 1 FROM Question WHERE id='dea-biblio-quiz-1-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q5-o2', 'dea-biblio-quiz-1-q5', '100', 0, 2 FROM Question WHERE id='dea-biblio-quiz-1-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q5-o3', 'dea-biblio-quiz-1-q5', '200', 0, 3 FROM Question WHERE id='dea-biblio-quiz-1-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q5-o4', 'dea-biblio-quiz-1-q5', '500', 1, 4 FROM Question WHERE id='dea-biblio-quiz-1-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q5-o5', 'dea-biblio-quiz-1-q5', '5.000', 0, 5 FROM Question WHERE id='dea-biblio-quiz-1-q5';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-1-q6', 'dea-biblio-quiz-1', 'Hubungan analisis bibliometrik dengan telaah sistematik dan meta-analisis menurut Donthu dkk. adalah', 'Donthu dkk. menyatakan ketiga metode saling melengkapi dan pilihannya bergantung pada tujuan telaah serta besar dan sifat pustaka yang ditelaah. Analisis bibliometrik merangkum struktur suatu bidang sedangkan meta-analisis merangkum bukti empiris tentang arah dan besar efek.', 6 FROM Quiz WHERE id='dea-biblio-quiz-1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q6-o1', 'dea-biblio-quiz-1-q6', 'Analisis bibliometrik menggantikan keduanya', 0, 1 FROM Question WHERE id='dea-biblio-quiz-1-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q6-o2', 'dea-biblio-quiz-1-q6', 'Analisis bibliometrik hanya sah bila didahului meta-analisis', 0, 2 FROM Question WHERE id='dea-biblio-quiz-1-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q6-o3', 'dea-biblio-quiz-1-q6', 'Ketiganya menjawab pertanyaan yang sama dengan cara berbeda', 0, 3 FROM Question WHERE id='dea-biblio-quiz-1-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q6-o4', 'dea-biblio-quiz-1-q6', 'Telaah sistematik tidak diperlukan lagi bila pustaka sudah dipetakan', 0, 4 FROM Question WHERE id='dea-biblio-quiz-1-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q6-o5', 'dea-biblio-quiz-1-q6', 'Ketiganya saling melengkapi dan pilihannya bergantung pada tujuan telaah serta besar dan sifat pustakanya', 1, 5 FROM Question WHERE id='dea-biblio-quiz-1-q6';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-1-q7', 'dea-biblio-quiz-1', 'Pernyataan yang benar tentang pedoman pelaporan BIBLIO adalah', 'BIBLIO memuat 20 butir yang disusun Montazeri dkk. melalui telaah pustaka dan Delphi empat putaran. Penyusunnya menyatakan pedoman ini masih awal dan belum ada bukti tentang mutu dan kegunaannya. Penyesuaian butir PRISMA 2020 adalah ciri PRIBA. Sepuluh prinsip adalah Leiden Manifesto. Tiga puluh dua butir calon adalah hasil telaah pendahuluan GLOBAL.', 7 FROM Quiz WHERE id='dea-biblio-quiz-1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q7-o1', 'dea-biblio-quiz-1-q7', 'Berisi 20 butir, disusun melalui telaah pustaka dan proses Delphi, dan masih berstatus awal', 1, 1 FROM Question WHERE id='dea-biblio-quiz-1-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q7-o2', 'dea-biblio-quiz-1-q7', 'Berisi 27 butir dan wajib bagi semua jurnal', 0, 2 FROM Question WHERE id='dea-biblio-quiz-1-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q7-o3', 'dea-biblio-quiz-1-q7', 'Disusun dengan menyesuaikan butir PRISMA 2020 tanpa proses konsensus', 0, 3 FROM Question WHERE id='dea-biblio-quiz-1-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q7-o4', 'dea-biblio-quiz-1-q7', 'Merupakan sepuluh prinsip penilaian penelitian', 0, 4 FROM Question WHERE id='dea-biblio-quiz-1-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q7-o5', 'dea-biblio-quiz-1-q7', 'Masih berupa 32 butir calon yang menunggu proses Delphi', 0, 5 FROM Question WHERE id='dea-biblio-quiz-1-q7';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-1-q8', 'dea-biblio-quiz-1', 'Jumlah butir pada usulan PRIBA adalah', 'PRIBA memuat 25 butir dalam tujuh bagian yang disesuaikan dari PRISMA 2020. BIBLIO memuat 20 butir. Leiden Manifesto memuat 10 prinsip. DORA memuat 18 rekomendasi. Telaah pendahuluan GLOBAL menghasilkan 32 butir calon.', 8 FROM Quiz WHERE id='dea-biblio-quiz-1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q8-o1', 'dea-biblio-quiz-1-q8', '10', 0, 1 FROM Question WHERE id='dea-biblio-quiz-1-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q8-o2', 'dea-biblio-quiz-1-q8', '18', 0, 2 FROM Question WHERE id='dea-biblio-quiz-1-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q8-o3', 'dea-biblio-quiz-1-q8', '20', 0, 3 FROM Question WHERE id='dea-biblio-quiz-1-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q8-o4', 'dea-biblio-quiz-1-q8', '25', 1, 4 FROM Question WHERE id='dea-biblio-quiz-1-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q8-o5', 'dea-biblio-quiz-1-q8', '32', 0, 5 FROM Question WHERE id='dea-biblio-quiz-1-q8';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-1-q9', 'dea-biblio-quiz-1', 'Sebuah naskah bibliometrik menulis bahwa studi dilakukan sesuai PRISMA 2020. Penilaian yang paling tepat adalah', 'PRISMA 2020 adalah pedoman pelaporan telaah sistematik. Dalam studi bibliometrik yang lazim dipinjam hanya diagram alirnya untuk menunjukkan jumlah rekaman pada tiap tahap seleksi. Butir seperti penilaian risiko bias dan sintesis efek tidak berlaku. Pedoman yang lebih sesuai adalah BIBLIO atau usulan PRIBA.', 9 FROM Quiz WHERE id='dea-biblio-quiz-1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q9-o1', 'dea-biblio-quiz-1-q9', 'Tepat karena PRISMA berlaku untuk semua jenis telaah', 0, 1 FROM Question WHERE id='dea-biblio-quiz-1-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q9-o2', 'dea-biblio-quiz-1-q9', 'Kurang tepat karena sebagian besar butir PRISMA seperti penilaian risiko bias tidak berlaku. Yang lazim dipinjam hanya diagram alirnya', 1, 2 FROM Question WHERE id='dea-biblio-quiz-1-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q9-o3', 'dea-biblio-quiz-1-q9', 'Tepat asalkan memakai dua basis data', 0, 3 FROM Question WHERE id='dea-biblio-quiz-1-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q9-o4', 'dea-biblio-quiz-1-q9', 'Kurang tepat karena PRISMA hanya untuk uji klinis', 0, 4 FROM Question WHERE id='dea-biblio-quiz-1-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q9-o5', 'dea-biblio-quiz-1-q9', 'Tepat karena PRISMA tidak memiliki butir tentang sintesis', 0, 5 FROM Question WHERE id='dea-biblio-quiz-1-q9';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-1-q10', 'dea-biblio-quiz-1', 'Rekomendasi umum DORA berisi anjuran untuk', 'Rekomendasi umum DORA adalah tidak memakai metrik berbasis jurnal seperti Journal Impact Factor sebagai ukuran pengganti mutu artikel, untuk menilai sumbangan seorang ilmuwan, atau dalam keputusan perekrutan, promosi, dan pendanaan. DORA tidak meminta semua indikator dihapus.', 10 FROM Quiz WHERE id='dea-biblio-quiz-1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q10-o1', 'dea-biblio-quiz-1-q10', 'Memakai Journal Impact Factor sebagai ukuran utama mutu artikel', 0, 1 FROM Question WHERE id='dea-biblio-quiz-1-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q10-o2', 'dea-biblio-quiz-1-q10', 'Menghapus seluruh indikator kuantitatif dari penilaian penelitian', 0, 2 FROM Question WHERE id='dea-biblio-quiz-1-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q10-o3', 'dea-biblio-quiz-1-q10', 'Tidak memakai metrik berbasis jurnal seperti Journal Impact Factor sebagai pengganti ukuran mutu artikel atau untuk menilai sumbangan seorang ilmuwan', 1, 3 FROM Question WHERE id='dea-biblio-quiz-1-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-1-q10-o4', 'dea-biblio-quiz-1-q10', 'Menilai peneliti hanya dari indeks h', 0, 4 FROM Question WHERE id='dea-biblio-quiz-1-q10';
