INSERT OR IGNORE INTO Topic (id,categoryId,title,description,"order",published) SELECT 'dea-biblio-group-2', 'cmv3voewj000dv1igg3ey1n7c', 'Teknik dan Ragam Studi', 'Bab 04–05', 2, 1 FROM Category WHERE id='cmv3voewj000dv1igg3ey1n7c';
INSERT OR IGNORE INTO Quiz (id,topicId,title,passingScore,published,isFree) SELECT 'dea-biblio-quiz-2', 'dea-biblio-group-2', 'Kuis 2. Teknik dan Ragam Studi', 70, 1, 0 FROM Topic WHERE id='dea-biblio-group-2';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-2-q1', 'dea-biblio-quiz-2', 'Dua keluarga teknik dalam analisis bibliometrik adalah', 'Analisis kinerja menghitung sumbangan tiap unsur penelitian seperti penulis, institusi, negara, dan jurnal. Pemetaan sains menggambarkan hubungan antarunsur itu dalam bentuk jaringan.', 1 FROM Quiz WHERE id='dea-biblio-quiz-2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q1-o1', 'dea-biblio-quiz-2-q1', 'Analisis univariat dan multivariat', 0, 1 FROM Question WHERE id='dea-biblio-quiz-2-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q1-o2', 'dea-biblio-quiz-2-q1', 'Analisis kualitatif dan kuantitatif', 0, 2 FROM Question WHERE id='dea-biblio-quiz-2-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q1-o3', 'dea-biblio-quiz-2-q1', 'Analisis primer dan sekunder', 0, 3 FROM Question WHERE id='dea-biblio-quiz-2-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q1-o4', 'dea-biblio-quiz-2-q1', 'Analisis kinerja dan pemetaan sains', 1, 4 FROM Question WHERE id='dea-biblio-quiz-2-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q1-o5', 'dea-biblio-quiz-2-q1', 'Analisis deskriptif dan inferensial', 0, 5 FROM Question WHERE id='dea-biblio-quiz-2-q1';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-2-q2', 'dea-biblio-quiz-2', 'Seorang penulis memiliki tujuh terbitan dengan jumlah sitasi 25, 14, 9, 5, 4, 2, dan 0. Indeks h penulis itu adalah', 'Terbitan diurutkan dari yang paling banyak disitasi. Terbitan peringkat keempat disitasi 5 kali sehingga masih memenuhi syarat sedikitnya 4 sitasi. Terbitan peringkat kelima hanya disitasi 4 kali sehingga tidak memenuhi syarat sedikitnya 5 sitasi. Indeks h adalah 4.', 2 FROM Quiz WHERE id='dea-biblio-quiz-2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q2-o1', 'dea-biblio-quiz-2-q2', '2', 0, 1 FROM Question WHERE id='dea-biblio-quiz-2-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q2-o2', 'dea-biblio-quiz-2-q2', '3', 0, 2 FROM Question WHERE id='dea-biblio-quiz-2-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q2-o3', 'dea-biblio-quiz-2-q2', '4', 1, 3 FROM Question WHERE id='dea-biblio-quiz-2-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q2-o4', 'dea-biblio-quiz-2-q2', '5', 0, 4 FROM Question WHERE id='dea-biblio-quiz-2-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q2-o5', 'dea-biblio-quiz-2-q2', '7', 0, 5 FROM Question WHERE id='dea-biblio-quiz-2-q2';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-2-q3', 'dea-biblio-quiz-2', 'Dua artikel disebut memiliki hubungan ko-sitasi bila', 'Ko-sitasi terjadi bila dua terbitan sama-sama disitasi oleh terbitan ketiga. Bila dua terbitan sama-sama menyitasi rujukan yang sama, hubungannya adalah bibliographic coupling. Kata kunci yang sama membentuk tautan ko-kata dan penulis yang sama membentuk tautan ko-kepengarangan.', 3 FROM Quiz WHERE id='dea-biblio-quiz-2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q3-o1', 'dea-biblio-quiz-2-q3', 'Artikel pertama menyitasi artikel kedua', 0, 1 FROM Question WHERE id='dea-biblio-quiz-2-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q3-o2', 'dea-biblio-quiz-2-q3', 'Keduanya ditulis oleh penulis yang sama', 0, 2 FROM Question WHERE id='dea-biblio-quiz-2-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q3-o3', 'dea-biblio-quiz-2-q3', 'Keduanya memakai kata kunci yang sama', 0, 3 FROM Question WHERE id='dea-biblio-quiz-2-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q3-o4', 'dea-biblio-quiz-2-q3', 'Keduanya menyitasi rujukan yang sama', 0, 4 FROM Question WHERE id='dea-biblio-quiz-2-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q3-o5', 'dea-biblio-quiz-2-q3', 'Keduanya disitasi bersama oleh artikel ketiga', 1, 5 FROM Question WHERE id='dea-biblio-quiz-2-q3';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-2-q4', 'dea-biblio-quiz-2', 'Teknik yang paling sesuai untuk melihat arah penelitian terkini dan terbitan baru yang belum banyak disitasi adalah', 'Tautan bibliographic coupling dibentuk dari daftar rujukan yang sudah ada sejak artikel terbit sehingga terbitan baru langsung dapat dipetakan. Ko-sitasi bergantung pada sitasi dari terbitan yang datang kemudian sehingga lebih cocok untuk menelusuri akar dan karya landasan suatu bidang.', 4 FROM Quiz WHERE id='dea-biblio-quiz-2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q4-o1', 'dea-biblio-quiz-2-q4', 'Bibliographic coupling', 1, 1 FROM Question WHERE id='dea-biblio-quiz-2-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q4-o2', 'dea-biblio-quiz-2-q4', 'Ko-sitasi', 0, 2 FROM Question WHERE id='dea-biblio-quiz-2-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q4-o3', 'dea-biblio-quiz-2-q4', 'Analisis jumlah sitasi', 0, 3 FROM Question WHERE id='dea-biblio-quiz-2-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q4-o4', 'dea-biblio-quiz-2-q4', 'Hukum Bradford', 0, 4 FROM Question WHERE id='dea-biblio-quiz-2-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q4-o5', 'dea-biblio-quiz-2-q4', 'Indeks g', 0, 5 FROM Question WHERE id='dea-biblio-quiz-2-q4';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-2-q5', 'dea-biblio-quiz-2', 'Tujuan penelitian adalah mengenali tema utama dan hotspot suatu bidang. Teknik dan data yang dibutuhkan adalah', 'Struktur konseptual suatu bidang diungkap dengan analisis ko-kata. Data yang dibutuhkan adalah judul, abstrak, dan kata kunci. Data tentang penulis dan negara saja tidak cukup untuk mengenali klaster topik.', 5 FROM Quiz WHERE id='dea-biblio-quiz-2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q5-o1', 'dea-biblio-quiz-2-q5', 'Ko-kepengarangan dengan data afiliasi', 0, 1 FROM Question WHERE id='dea-biblio-quiz-2-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q5-o2', 'dea-biblio-quiz-2-q5', 'Ko-kata dengan data judul, abstrak, dan kata kunci', 1, 2 FROM Question WHERE id='dea-biblio-quiz-2-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q5-o3', 'dea-biblio-quiz-2-q5', 'Analisis kinerja dengan data tahun terbit', 0, 3 FROM Question WHERE id='dea-biblio-quiz-2-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q5-o4', 'dea-biblio-quiz-2-q5', 'Ko-sitasi dengan data nama jurnal', 0, 4 FROM Question WHERE id='dea-biblio-quiz-2-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q5-o5', 'dea-biblio-quiz-2-q5', 'Indeks h dengan data jumlah sitasi', 0, 5 FROM Question WHERE id='dea-biblio-quiz-2-q5';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-2-q6', 'dea-biblio-quiz-2', 'Analisis ko-kepengarangan mengungkap struktur', 'Ko-kepengarangan menunjukkan siapa bekerja sama dengan siapa pada tingkat penulis, institusi, atau negara sehingga yang terungkap adalah struktur sosial. Struktur konseptual diungkap ko-kata. Struktur intelektual diungkap analisis berbasis sitasi.', 6 FROM Quiz WHERE id='dea-biblio-quiz-2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q6-o1', 'dea-biblio-quiz-2-q6', 'Konseptual', 0, 1 FROM Question WHERE id='dea-biblio-quiz-2-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q6-o2', 'dea-biblio-quiz-2-q6', 'Intelektual', 0, 2 FROM Question WHERE id='dea-biblio-quiz-2-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q6-o3', 'dea-biblio-quiz-2-q6', 'Sosial', 1, 3 FROM Question WHERE id='dea-biblio-quiz-2-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q6-o4', 'dea-biblio-quiz-2-q6', 'Temporal', 0, 4 FROM Question WHERE id='dea-biblio-quiz-2-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q6-o5', 'dea-biblio-quiz-2-q6', 'Metodologis', 0, 5 FROM Question WHERE id='dea-biblio-quiz-2-q6';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-2-q7', 'dea-biblio-quiz-2', 'Pernyataan yang benar tentang indeks h adalah', 'Indeks h bergantung pada basis data yang dipakai, lama karier, dan kebiasaan sitasi tiap bidang. Nilai seorang penulis di Scopus, Web of Science, dan Google Scholar hampir selalu berbeda. Naskah harus menyebut sumbernya.', 7 FROM Quiz WHERE id='dea-biblio-quiz-2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q7-o1', 'dea-biblio-quiz-2-q7', 'Nilainya sama di semua basis data', 0, 1 FROM Question WHERE id='dea-biblio-quiz-2-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q7-o2', 'dea-biblio-quiz-2-q7', 'Tidak dipengaruhi lama karier', 0, 2 FROM Question WHERE id='dea-biblio-quiz-2-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q7-o3', 'dea-biblio-quiz-2-q7', 'Dapat dibandingkan langsung antarbidang ilmu', 0, 3 FROM Question WHERE id='dea-biblio-quiz-2-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q7-o4', 'dea-biblio-quiz-2-q7', 'Nilainya bergantung pada basis data yang dipakai sehingga sumbernya harus disebut', 1, 4 FROM Question WHERE id='dea-biblio-quiz-2-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q7-o5', 'dea-biblio-quiz-2-q7', 'Hanya menghitung jumlah terbitan', 0, 5 FROM Question WHERE id='dea-biblio-quiz-2-q7';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-2-q8', 'dea-biblio-quiz-2', 'Hukum yang menggambarkan bahwa sekelompok kecil jurnal inti memuat bagian besar artikel tentang suatu topik adalah', 'Hukum Bradford menggambarkan sebaran artikel pada jurnal dengan sekelompok kecil jurnal inti yang memuat bagian besar artikel. Hukum Lotka menggambarkan produktivitas penulis. Hukum Zipf menggambarkan frekuensi kata.', 8 FROM Quiz WHERE id='dea-biblio-quiz-2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q8-o1', 'dea-biblio-quiz-2-q8', 'Hukum Lotka', 0, 1 FROM Question WHERE id='dea-biblio-quiz-2-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q8-o2', 'dea-biblio-quiz-2-q8', 'Hukum Zipf', 0, 2 FROM Question WHERE id='dea-biblio-quiz-2-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q8-o3', 'dea-biblio-quiz-2-q8', 'Hukum Hirsch', 0, 3 FROM Question WHERE id='dea-biblio-quiz-2-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q8-o4', 'dea-biblio-quiz-2-q8', 'Hukum Pritchard', 0, 4 FROM Question WHERE id='dea-biblio-quiz-2-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q8-o5', 'dea-biblio-quiz-2-q8', 'Hukum Bradford', 1, 5 FROM Question WHERE id='dea-biblio-quiz-2-q8';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-2-q9', 'dea-biblio-quiz-2', 'Öztürk dkk. merumuskan empat tahap studi bibliometrik. Urutan yang benar adalah', 'Empat tahap menurut Öztürk dkk. adalah menetapkan tujuan penelitian, mengumpulkan data, menganalisis dan memvisualkan, serta menafsirkan temuan dan hasil. Tujuan ditetapkan paling awal karena menentukan jenis data dan analisis.', 9 FROM Quiz WHERE id='dea-biblio-quiz-2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q9-o1', 'dea-biblio-quiz-2-q9', 'Menetapkan tujuan, mengumpulkan data, menganalisis dan memvisualkan, menafsirkan temuan', 1, 1 FROM Question WHERE id='dea-biblio-quiz-2-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q9-o2', 'dea-biblio-quiz-2-q9', 'Mengumpulkan data, menetapkan tujuan, menganalisis, menafsirkan', 0, 2 FROM Question WHERE id='dea-biblio-quiz-2-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q9-o3', 'dea-biblio-quiz-2-q9', 'Menetapkan tujuan, menganalisis, mengumpulkan data, menafsirkan', 0, 3 FROM Question WHERE id='dea-biblio-quiz-2-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q9-o4', 'dea-biblio-quiz-2-q9', 'Memvisualkan, menetapkan tujuan, mengumpulkan data, menulis', 0, 4 FROM Question WHERE id='dea-biblio-quiz-2-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q9-o5', 'dea-biblio-quiz-2-q9', 'Mengumpulkan data, memvisualkan, menafsirkan, menetapkan tujuan', 0, 5 FROM Question WHERE id='dea-biblio-quiz-2-q9';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-2-q10', 'dea-biblio-quiz-2', 'Menurut Perianes-Rodriguez dkk. perbedaan hitung penuh dan hitung fraksional dalam membangun jaringan adalah', 'Pada hitung penuh setiap terbitan bersama dihitung satu untuk tiap pasangan. Pada hitung fraksional bobot sebuah terbitan dibagi menurut banyaknya penulis atau rujukannya. Kedua cara dapat memberi hasil yang sangat berbeda sehingga cara yang dipakai harus dilaporkan.', 10 FROM Quiz WHERE id='dea-biblio-quiz-2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q10-o1', 'dea-biblio-quiz-2-q10', 'Hitung penuh hanya dipakai untuk kata kunci', 0, 1 FROM Question WHERE id='dea-biblio-quiz-2-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q10-o2', 'dea-biblio-quiz-2-q10', 'Hitung fraksional membagi bobot sebuah terbitan menurut banyaknya penulis atau rujukannya dan kedua cara dapat memberi hasil yang sangat berbeda', 1, 2 FROM Question WHERE id='dea-biblio-quiz-2-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q10-o3', 'dea-biblio-quiz-2-q10', 'Keduanya selalu memberi hasil yang sama', 0, 3 FROM Question WHERE id='dea-biblio-quiz-2-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q10-o4', 'dea-biblio-quiz-2-q10', 'Hitung fraksional menghapus terbitan dengan banyak penulis', 0, 4 FROM Question WHERE id='dea-biblio-quiz-2-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-2-q10-o5', 'dea-biblio-quiz-2-q10', 'Hitung penuh tidak dapat dipakai pada VOSviewer', 0, 5 FROM Question WHERE id='dea-biblio-quiz-2-q10';
