INSERT OR IGNORE INTO Topic (id,categoryId,title,description,"order",published) SELECT 'dea-biblio-group-3', 'cmv3voewj000dv1igg3ey1n7c', 'Merancang Studi', 'Bab 06–10', 3, 1 FROM Category WHERE id='cmv3voewj000dv1igg3ey1n7c';
INSERT OR IGNORE INTO Quiz (id,topicId,title,passingScore,published,isFree) SELECT 'dea-biblio-quiz-3', 'dea-biblio-group-3', 'Kuis 3. Merancang Studi', 70, 1, 0 FROM Topic WHERE id='dea-biblio-group-3';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-3-q1', 'dea-biblio-quiz-3', 'Penelusuran pendahuluan menemukan tujuh naskah bibliometrik yang sudah terbit tentang topik yang direncanakan. Langkah yang paling tepat adalah', 'Adanya studi terdahulu tidak selalu berarti topik harus ditinggalkan. Koo dan Lin meminta alasan yang jelas dan meyakinkan bagi studi baru. Alasan itu ditulis pada pendahuluan dan studi terdahulu dibandingkan pada diskusi.', 1 FROM Quiz WHERE id='dea-biblio-quiz-3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q1-o1', 'dea-biblio-quiz-3-q1', 'Tetap mengerjakan tanpa menyebut studi terdahulu', 0, 1 FROM Question WHERE id='dea-biblio-quiz-3-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q1-o2', 'dea-biblio-quiz-3-q1', 'Mengganti kata bibliometric pada judul dengan kata lain', 0, 2 FROM Question WHERE id='dea-biblio-quiz-3-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q1-o3', 'dea-biblio-quiz-3-q1', 'Menetapkan alasan yang jelas bagi studi baru, misalnya periode yang lebih baru atau fokus berbeda, lalu membandingkan dengan studi terdahulu', 1, 3 FROM Question WHERE id='dea-biblio-quiz-3-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q1-o4', 'dea-biblio-quiz-3-q1', 'Meninggalkan topik karena tidak boleh ada studi kedua', 0, 4 FROM Question WHERE id='dea-biblio-quiz-3-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q1-o5', 'dea-biblio-quiz-3-q1', 'Menyalin string pencarian studi terdahulu tanpa perubahan', 0, 5 FROM Question WHERE id='dea-biblio-quiz-3-q1';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-3-q2', 'dea-biblio-quiz-3', 'Penelusuran pendahuluan untuk sebuah topik menghasilkan lima rekaman. Kesimpulan yang paling tepat adalah', 'Jaringan dari segelintir rekaman terlalu jarang untuk dipetakan. Topik perlu diperluas atau dipilih jenis telaah lain seperti scoping review. Analisis bibliometrik cocok untuk kumpulan data yang besar.', 2 FROM Quiz WHERE id='dea-biblio-quiz-3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q2-o1', 'dea-biblio-quiz-3-q2', 'Topik ideal untuk analisis bibliometrik', 0, 1 FROM Question WHERE id='dea-biblio-quiz-3-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q2-o2', 'dea-biblio-quiz-3-q2', 'Topik terlalu luas sehingga perlu dipersempit', 0, 2 FROM Question WHERE id='dea-biblio-quiz-3-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q2-o3', 'dea-biblio-quiz-3-q2', 'Ambang kata kunci perlu dinaikkan', 0, 3 FROM Question WHERE id='dea-biblio-quiz-3-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q2-o4', 'dea-biblio-quiz-3-q2', 'Topik terlalu sempit sehingga perlu diperluas atau diganti dengan jenis telaah lain', 1, 4 FROM Question WHERE id='dea-biblio-quiz-3-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q2-o5', 'dea-biblio-quiz-3-q2', 'Basis data perlu diganti dengan Google Scholar', 0, 5 FROM Question WHERE id='dea-biblio-quiz-3-q2';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-3-q3', 'dea-biblio-quiz-3', 'Judul yang paling memenuhi anjuran BIBLIO dan PRIBA adalah', 'Judul yang baik memuat topik, jenis studi, dan periode cakupan dengan tahun awal dan akhir. Sumber data dapat disebut bila ruang memungkinkan. Menyebut lama waktu tanpa tahun tidak informatif. Kata efektivitas menjanjikan simpulan yang tidak dapat diberikan metode ini.', 3 FROM Quiz WHERE id='dea-biblio-quiz-3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q3-o1', 'dea-biblio-quiz-3-q3', 'Kecerdasan buatan pada tuberkulosis', 0, 1 FROM Question WHERE id='dea-biblio-quiz-3-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q3-o2', 'dea-biblio-quiz-3-q3', 'Analisis VOSviewer tentang tuberkulosis', 0, 2 FROM Question WHERE id='dea-biblio-quiz-3-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q3-o3', 'dea-biblio-quiz-3-q3', 'Dua puluh tahun penelitian tuberkulosis: sebuah studi', 0, 3 FROM Question WHERE id='dea-biblio-quiz-3-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q3-o4', 'dea-biblio-quiz-3-q3', 'Efektivitas kecerdasan buatan pada tuberkulosis: analisis bibliometrik', 0, 4 FROM Question WHERE id='dea-biblio-quiz-3-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q3-o5', 'dea-biblio-quiz-3-q3', 'Kecerdasan buatan pada tuberkulosis: analisis bibliometrik terbitan terindeks PubMed tahun 2015 sampai 2025', 1, 5 FROM Question WHERE id='dea-biblio-quiz-3-q3';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-3-q4', 'dea-biblio-quiz-3', 'Dari 100 studi bibliometrik bidang kesehatan yang ditelaah Koo dan Lin, persentase yang menyebut periode cakupan pada judul adalah', 'Hanya 24% studi yang menyebut periode cakupan pada judul. Sebanyak 73% menyebut jenis studinya pada judul. Judul yang memuat periode karena itu sudah lebih lengkap daripada sebagian besar studi yang terbit.', 4 FROM Quiz WHERE id='dea-biblio-quiz-3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q4-o1', 'dea-biblio-quiz-3-q4', '24%', 1, 1 FROM Question WHERE id='dea-biblio-quiz-3-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q4-o2', 'dea-biblio-quiz-3-q4', '60%', 0, 2 FROM Question WHERE id='dea-biblio-quiz-3-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q4-o3', 'dea-biblio-quiz-3-q4', '73%', 0, 3 FROM Question WHERE id='dea-biblio-quiz-3-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q4-o4', 'dea-biblio-quiz-3-q4', '86%', 0, 4 FROM Question WHERE id='dea-biblio-quiz-3-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q4-o5', 'dea-biblio-quiz-3-q4', '100%', 0, 5 FROM Question WHERE id='dea-biblio-quiz-3-q4';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-3-q5', 'dea-biblio-quiz-3', 'Pertanyaan penelitian tentang karya yang menjadi landasan suatu bidang memerlukan data berupa', 'Karya landasan ditelusuri dengan analisis ko-sitasi yang memerlukan daftar rujukan tiap terbitan. Data itu tersedia pada ekspor Web of Science dan Scopus tetapi tidak pada ekspor PubMed.', 5 FROM Quiz WHERE id='dea-biblio-quiz-3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q5-o1', 'dea-biblio-quiz-3-q5', 'Daftar rujukan tiap terbitan', 1, 1 FROM Question WHERE id='dea-biblio-quiz-3-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q5-o2', 'dea-biblio-quiz-3-q5', 'Tahun terbit', 0, 2 FROM Question WHERE id='dea-biblio-quiz-3-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q5-o3', 'dea-biblio-quiz-3-q5', 'Nama jurnal', 0, 3 FROM Question WHERE id='dea-biblio-quiz-3-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q5-o4', 'dea-biblio-quiz-3-q5', 'Kata kunci penulis', 0, 4 FROM Question WHERE id='dea-biblio-quiz-3-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q5-o5', 'dea-biblio-quiz-3-q5', 'Negara afiliasi', 0, 5 FROM Question WHERE id='dea-biblio-quiz-3-q5';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-3-q6', 'dea-biblio-quiz-3', 'Analisis yang TIDAK dapat dikerjakan VOSviewer dengan berkas ekspor PubMed adalah', 'Manual VOSviewer menyatakan bahwa data yang diekspor dari PubMed tidak dapat dipakai untuk mengenali tautan sitasi, bibliographic coupling, dan ko-sitasi. Ko-kepengarangan dan ko-kemunculan tetap dapat dikerjakan.', 6 FROM Quiz WHERE id='dea-biblio-quiz-3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q6-o1', 'dea-biblio-quiz-3-q6', 'Ko-kepengarangan penulis', 0, 1 FROM Question WHERE id='dea-biblio-quiz-3-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q6-o2', 'dea-biblio-quiz-3-q6', 'Ko-sitasi', 1, 2 FROM Question WHERE id='dea-biblio-quiz-3-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q6-o3', 'dea-biblio-quiz-3-q6', 'Ko-kemunculan kata kunci', 0, 3 FROM Question WHERE id='dea-biblio-quiz-3-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q6-o4', 'dea-biblio-quiz-3-q6', 'Ko-kepengarangan negara', 0, 4 FROM Question WHERE id='dea-biblio-quiz-3-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q6-o5', 'dea-biblio-quiz-3-q6', 'Ko-kemunculan istilah dari judul dan abstrak', 0, 5 FROM Question WHERE id='dea-biblio-quiz-3-q6';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-3-q7', 'dea-biblio-quiz-3', 'Menurut manual VOSviewer versi 1.6.20 batas sekali ekspor dari Scopus adalah', 'Manual VOSviewer menyebut batas sekali ekspor 500 dokumen untuk Web of Science dan 2.000 dokumen untuk Scopus. Versi gratis Dimensions membatasi 2.500 dokumen, PubMed 10.000 dokumen, dan Lens 50.000 dokumen. Data yang lebih besar diekspor dalam beberapa berkas.', 7 FROM Quiz WHERE id='dea-biblio-quiz-3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q7-o1', 'dea-biblio-quiz-3-q7', '500 dokumen', 0, 1 FROM Question WHERE id='dea-biblio-quiz-3-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q7-o2', 'dea-biblio-quiz-3-q7', '2.000 dokumen', 1, 2 FROM Question WHERE id='dea-biblio-quiz-3-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q7-o3', 'dea-biblio-quiz-3-q7', '2.500 dokumen', 0, 3 FROM Question WHERE id='dea-biblio-quiz-3-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q7-o4', 'dea-biblio-quiz-3-q7', '10.000 dokumen', 0, 4 FROM Question WHERE id='dea-biblio-quiz-3-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q7-o5', 'dea-biblio-quiz-3-q7', '50.000 dokumen', 0, 5 FROM Question WHERE id='dea-biblio-quiz-3-q7';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-3-q8', 'dea-biblio-quiz-3', 'Temuan Mongeon dan Paul-Hus tentang Web of Science dan Scopus adalah', 'Kedua basis data condong pada ilmu alam, teknik, dan biomedis serta pada jurnal berbahasa Inggris. Cakupan keduanya juga berbeda cukup besar sehingga hasil analisis bibliometrik dapat berubah menurut basis data yang dipakai.', 8 FROM Quiz WHERE id='dea-biblio-quiz-3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q8-o1', 'dea-biblio-quiz-3-q8', 'Cakupan keduanya identik sehingga hasil analisis selalu sama', 0, 1 FROM Question WHERE id='dea-biblio-quiz-3-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q8-o2', 'dea-biblio-quiz-3-q8', 'Keduanya lebih banyak memuat ilmu sosial daripada biomedis', 0, 2 FROM Question WHERE id='dea-biblio-quiz-3-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q8-o3', 'dea-biblio-quiz-3-q8', 'Keduanya lebih banyak memuat ilmu alam, teknik, dan biomedis serta jurnal berbahasa Inggris, dan cakupan keduanya berbeda cukup besar', 1, 3 FROM Question WHERE id='dea-biblio-quiz-3-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q8-o4', 'dea-biblio-quiz-3-q8', 'Keduanya tidak memuat jurnal berbahasa Inggris', 0, 4 FROM Question WHERE id='dea-biblio-quiz-3-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q8-o5', 'dea-biblio-quiz-3-q8', 'Scopus hanya memuat buku', 0, 5 FROM Question WHERE id='dea-biblio-quiz-3-q8';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-3-q9', 'dea-biblio-quiz-3', 'Dalam menyusun string pencarian, sinonim untuk satu konsep digabung dengan operator', 'Sinonim, ejaan lain, dan singkatan di dalam satu konsep digabung dengan OR agar semuanya terjaring. Antarkonsep digabung dengan AND agar hanya terbitan yang memuat semua konsep yang terambil.', 9 FROM Quiz WHERE id='dea-biblio-quiz-3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q9-o1', 'dea-biblio-quiz-3-q9', 'AND', 0, 1 FROM Question WHERE id='dea-biblio-quiz-3-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q9-o2', 'dea-biblio-quiz-3-q9', 'NOT', 0, 2 FROM Question WHERE id='dea-biblio-quiz-3-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q9-o3', 'dea-biblio-quiz-3-q9', 'NEAR', 0, 3 FROM Question WHERE id='dea-biblio-quiz-3-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q9-o4', 'dea-biblio-quiz-3-q9', 'OR', 1, 4 FROM Question WHERE id='dea-biblio-quiz-3-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q9-o5', 'dea-biblio-quiz-3-q9', 'WITH', 0, 5 FROM Question WHERE id='dea-biblio-quiz-3-q9';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-3-q10', 'dea-biblio-quiz-3', 'Mengapa tanggal penelusuran harus dicatat dan dilaporkan?', 'Basis data diperbarui terus sehingga jumlah rekaman dan jumlah sitasi berubah dari hari ke hari. Koo dan Lin menyarankan pengambilan data diselesaikan dalam waktu singkat, misalnya satu hari. Hanya 62% dari studi yang mereka telaah menyebut tanggal penelusuran.', 10 FROM Quiz WHERE id='dea-biblio-quiz-3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q10-o1', 'dea-biblio-quiz-3-q10', 'Karena basis data hanya dapat diakses pada tanggal tertentu', 0, 1 FROM Question WHERE id='dea-biblio-quiz-3-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q10-o2', 'dea-biblio-quiz-3-q10', 'Karena jurnal mensyaratkan penelusuran pada awal bulan', 0, 2 FROM Question WHERE id='dea-biblio-quiz-3-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q10-o3', 'dea-biblio-quiz-3-q10', 'Karena tanggal menentukan ambang kata kunci', 0, 3 FROM Question WHERE id='dea-biblio-quiz-3-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q10-o4', 'dea-biblio-quiz-3-q10', 'Karena tanggal menentukan jumlah klaster', 0, 4 FROM Question WHERE id='dea-biblio-quiz-3-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-3-q10-o5', 'dea-biblio-quiz-3-q10', 'Karena basis data terus diperbarui sehingga jumlah rekaman dan sitasi berubah menurut tanggal', 1, 5 FROM Question WHERE id='dea-biblio-quiz-3-q10';
