INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-4-q1', 'dea-biblio-quiz-4', 'Kata kunci chest X-ray, chest radiograph, dan CXR muncul sebagai tiga simpul terpisah pada peta. Cara yang tepat untuk mengatasinya adalah', 'Sinonim dan singkatan membuat satu konsep terpecah menjadi beberapa simpul kecil. Berkas tesaurus dipakai untuk menggabungkan sinonim, menyeragamkan ejaan, dan menggabungkan singkatan dengan kepanjangannya. Pemakaian tesaurus dilaporkan pada metode.', 1 FROM Quiz WHERE id='dea-biblio-quiz-4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q1-o1', 'dea-biblio-quiz-4-q1', 'Menggabungkannya dengan berkas tesaurus', 1, 1 FROM Question WHERE id='dea-biblio-quiz-4-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q1-o2', 'dea-biblio-quiz-4-q1', 'Menaikkan ambang kemunculan minimum', 0, 2 FROM Question WHERE id='dea-biblio-quiz-4-q1';
