INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q1-o4', 'dea-biblio-quiz-4-q1', 'Menghapus ketiganya dari peta', 0, 4 FROM Question WHERE id='dea-biblio-quiz-4-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q1-o5', 'dea-biblio-quiz-4-q1', 'Mengganti hitung penuh dengan hitung fraksional', 0, 5 FROM Question WHERE id='dea-biblio-quiz-4-q1';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-4-q2', 'dea-biblio-quiz-4', 'Berkas tesaurus VOSviewer terdiri atas dua kolom, yaitu', 'Berkas tesaurus VOSviewer adalah berkas teks dengan kolom label dan kolom replace by. Label pada kolom pertama diganti dengan isi kolom kedua. Bila kolom kedua dikosongkan, label itu diabaikan.', 2 FROM Quiz WHERE id='dea-biblio-quiz-4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q2-o1', 'dea-biblio-quiz-4-q2', 'author dan year', 0, 1 FROM Question WHERE id='dea-biblio-quiz-4-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q2-o2', 'dea-biblio-quiz-4-q2', 'label dan replace by', 1, 2 FROM Question WHERE id='dea-biblio-quiz-4-q2';
