INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-4-q3', 'dea-biblio-quiz-4', 'Jumlah terbitan suatu topik adalah 11 pada tahun pertama dan 240 pada tahun kesebelas. Pertumbuhan tahunan rata-rata secara majemuk dihitung dengan', 'Laju majemuk dihitung dari perbandingan jumlah tahun akhir terhadap tahun awal yang dipangkatkan dengan satu per banyak tahun dikurangi satu, lalu dikurangi satu. Untuk sebelas tahun pangkatnya adalah satu per sepuluh. Hasilnya 36,1%.', 3 FROM Quiz WHERE id='dea-biblio-quiz-4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q3-o1', 'dea-biblio-quiz-4-q3', '(240 dikurangi 11) dibagi 11', 0, 1 FROM Question WHERE id='dea-biblio-quiz-4-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q3-o2', 'dea-biblio-quiz-4-q3', '240 dibagi 11 lalu dibagi 11', 0, 2 FROM Question WHERE id='dea-biblio-quiz-4-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q3-o3', 'dea-biblio-quiz-4-q3', '(240 dibagi 11) pangkat (1 dibagi 10) lalu dikurangi 1', 1, 3 FROM Question WHERE id='dea-biblio-quiz-4-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q3-o4', 'dea-biblio-quiz-4-q3', '(240 dikurangi 11) dibagi 240', 0, 4 FROM Question WHERE id='dea-biblio-quiz-4-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q3-o5', 'dea-biblio-quiz-4-q3', '240 dibagi 11 pangkat 10', 0, 5 FROM Question WHERE id='dea-biblio-quiz-4-q3';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-4-q4', 'dea-biblio-quiz-4', 'Pada sebuah kumpulan data 83,9% penulis hanya muncul pada satu terbitan. Hukum yang dipakai sebagai pembanding adalah', 'Hukum Lotka menggambarkan produktivitas penulis. Jumlah penulis dengan n terbitan kira-kira sebanding dengan satu per n kuadrat dari jumlah penulis dengan satu terbitan sehingga sebagian besar penulis hanya muncul sekali.', 4 FROM Quiz WHERE id='dea-biblio-quiz-4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q4-o1', 'dea-biblio-quiz-4-q4', 'Hukum Bradford', 0, 1 FROM Question WHERE id='dea-biblio-quiz-4-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q4-o2', 'dea-biblio-quiz-4-q4', 'Hukum Zipf', 0, 2 FROM Question WHERE id='dea-biblio-quiz-4-q4';
