INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q4-o4', 'dea-biblio-quiz-4-q4', 'Hukum Lotka', 1, 4 FROM Question WHERE id='dea-biblio-quiz-4-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q4-o5', 'dea-biblio-quiz-4-q4', 'Indeks g', 0, 5 FROM Question WHERE id='dea-biblio-quiz-4-q4';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-4-q5', 'dea-biblio-quiz-4', 'Sitasi lokal pada laporan bibliometrik berarti', 'Sitasi global dihitung dari seluruh basis data. Sitasi lokal hanya berasal dari terbitan di dalam kumpulan data sehingga lebih menggambarkan pengaruh di dalam bidang itu sendiri. Jenis yang dipakai harus disebut.', 5 FROM Quiz WHERE id='dea-biblio-quiz-4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q5-o1', 'dea-biblio-quiz-4-q5', 'Sitasi dari penulis senegara', 0, 1 FROM Question WHERE id='dea-biblio-quiz-4-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q5-o2', 'dea-biblio-quiz-4-q5', 'Sitasi dari jurnal nasional', 0, 2 FROM Question WHERE id='dea-biblio-quiz-4-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q5-o3', 'dea-biblio-quiz-4-q5', 'Sitasi yang dihitung oleh Google Scholar', 0, 3 FROM Question WHERE id='dea-biblio-quiz-4-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q5-o4', 'dea-biblio-quiz-4-q5', 'Sitasi oleh penulisnya sendiri', 0, 4 FROM Question WHERE id='dea-biblio-quiz-4-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q5-o5', 'dea-biblio-quiz-4-q5', 'Sitasi yang berasal dari terbitan di dalam kumpulan data yang dianalisis', 1, 5 FROM Question WHERE id='dea-biblio-quiz-4-q5';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-4-q6', 'dea-biblio-quiz-4', 'Pada tampilan jaringan VOSviewer ukuran lingkaran sebuah butir menunjukkan', 'Butir dengan bobot lebih besar ditampilkan lebih menonjol. Pada peta kata kunci bobot itu umumnya jumlah kemunculan. Warna menunjukkan klaster pada tampilan jaringan dan garis menunjukkan tautan.', 6 FROM Quiz WHERE id='dea-biblio-quiz-4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q6-o1', 'dea-biblio-quiz-4-q6', 'Bobot butir, misalnya jumlah kemunculan kata kunci', 1, 1 FROM Question WHERE id='dea-biblio-quiz-4-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q6-o2', 'dea-biblio-quiz-4-q6', 'Tahun terbit rata-rata', 0, 2 FROM Question WHERE id='dea-biblio-quiz-4-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q6-o3', 'dea-biblio-quiz-4-q6', 'Nomor klaster', 0, 3 FROM Question WHERE id='dea-biblio-quiz-4-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q6-o4', 'dea-biblio-quiz-4-q6', 'Jarak ke pusat peta', 0, 4 FROM Question WHERE id='dea-biblio-quiz-4-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q6-o5', 'dea-biblio-quiz-4-q6', 'Jumlah penulis', 0, 5 FROM Question WHERE id='dea-biblio-quiz-4-q6';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-4-q7', 'dea-biblio-quiz-4', 'Pada tampilan overlay dengan skor rata-rata tahun terbit dan warna bawaan, kata kunci berwarna kuning berarti', 'Pada tampilan overlay warna mengikuti skor. Secara bawaan warna bergerak dari biru untuk skor terendah ke hijau lalu kuning untuk skor tertinggi. Bila skornya rata-rata tahun terbit, kuning menandai kata yang lebih baru.', 7 FROM Quiz WHERE id='dea-biblio-quiz-4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q7-o1', 'dea-biblio-quiz-4-q7', 'Paling sering muncul', 0, 1 FROM Question WHERE id='dea-biblio-quiz-4-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q7-o2', 'dea-biblio-quiz-4-q7', 'Rata-rata tahun terbitnya lebih baru', 1, 2 FROM Question WHERE id='dea-biblio-quiz-4-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q7-o3', 'dea-biblio-quiz-4-q7', 'Paling banyak tautannya', 0, 3 FROM Question WHERE id='dea-biblio-quiz-4-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q7-o4', 'dea-biblio-quiz-4-q7', 'Berada pada klaster terbesar', 0, 4 FROM Question WHERE id='dea-biblio-quiz-4-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q7-o5', 'dea-biblio-quiz-4-q7', 'Paling banyak disitasi', 0, 5 FROM Question WHERE id='dea-biblio-quiz-4-q7';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-4-q8', 'dea-biblio-quiz-4', 'Pernyataan yang benar tentang klaster pada VOSviewer adalah', 'Klaster pada VOSviewer tidak bertumpang tindih sehingga satu butir hanya masuk ke satu klaster. Perangkat hanya memberi nomor. Peneliti memberi nama setelah membaca anggota klaster. Jumlah klaster dipengaruhi nilai resolusi dan pengaturan lain.', 8 FROM Quiz WHERE id='dea-biblio-quiz-4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q8-o1', 'dea-biblio-quiz-4-q8', 'Satu butir dapat menjadi anggota beberapa klaster', 0, 1 FROM Question WHERE id='dea-biblio-quiz-4-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q8-o2', 'dea-biblio-quiz-4-q8', 'Nama klaster diberikan otomatis oleh perangkat lunak', 0, 2 FROM Question WHERE id='dea-biblio-quiz-4-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q8-o3', 'dea-biblio-quiz-4-q8', 'Satu butir hanya dapat menjadi anggota satu klaster dan nama klaster diberikan peneliti', 1, 3 FROM Question WHERE id='dea-biblio-quiz-4-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q8-o4', 'dea-biblio-quiz-4-q8', 'Jumlah klaster selalu empat', 0, 4 FROM Question WHERE id='dea-biblio-quiz-4-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q8-o5', 'dea-biblio-quiz-4-q8', 'Klaster tidak dipengaruhi pengaturan perangkat lunak', 0, 5 FROM Question WHERE id='dea-biblio-quiz-4-q8';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-4-q9', 'dea-biblio-quiz-4', 'Tiga perintah untuk membuka Biblioshiny di RStudio secara berurutan adalah', 'Paket bibliometrix dipasang dengan install.packages, dimuat dengan library, lalu antarmuka webnya dibuka dengan biblioshiny. Pemasangan cukup dilakukan sekali sedangkan dua perintah berikutnya dijalankan setiap kali memulai.', 9 FROM Quiz WHERE id='dea-biblio-quiz-4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q9-o1', 'dea-biblio-quiz-4-q9', 'library(biblioshiny), install(bibliometrix), run()', 0, 1 FROM Question WHERE id='dea-biblio-quiz-4-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q9-o2', 'dea-biblio-quiz-4-q9', 'biblioshiny(), library(shiny), install.packages("vosviewer")', 0, 2 FROM Question WHERE id='dea-biblio-quiz-4-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q9-o3', 'dea-biblio-quiz-4-q9', 'require(vosviewer), biblioshiny(), plot()', 0, 3 FROM Question WHERE id='dea-biblio-quiz-4-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q9-o4', 'dea-biblio-quiz-4-q9', 'install.packages("bibliometrix"), library(bibliometrix), biblioshiny()', 1, 4 FROM Question WHERE id='dea-biblio-quiz-4-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q9-o5', 'dea-biblio-quiz-4-q9', 'install.packages("biblioshiny"), start(), library(R)', 0, 5 FROM Question WHERE id='dea-biblio-quiz-4-q9';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-4-q10', 'dea-biblio-quiz-4', 'Urutan tiga tahap sensemaking menurut Lim dan Kumar adalah', 'Scanning adalah mengenali pola yang menonjol. Sensing adalah menggali sebab dan arti pola itu dengan pertanyaan bagaimana, mengapa, dan lalu apa. Substantiating adalah meneguhkan tafsir dengan bukti.', 10 FROM Quiz WHERE id='dea-biblio-quiz-4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q10-o1', 'dea-biblio-quiz-4-q10', 'Sensing, scanning, substantiating', 0, 1 FROM Question WHERE id='dea-biblio-quiz-4-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q10-o2', 'dea-biblio-quiz-4-q10', 'Substantiating, scanning, sensing', 0, 2 FROM Question WHERE id='dea-biblio-quiz-4-q10';
