INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-4-q10-o4', 'dea-biblio-quiz-4-q10', 'Sensing, substantiating, scanning', 0, 4 FROM Question WHERE id='dea-biblio-quiz-4-q10';
