INSERT OR IGNORE INTO Topic (id,categoryId,title,description,"order",published) SELECT 'dea-biblio-group-5', 'cmv3voewj000dv1igg3ey1n7c', 'Melaporkan dan Menerbitkan', 'Bab 16–19', 5, 1 FROM Category WHERE id='cmv3voewj000dv1igg3ey1n7c';
INSERT OR IGNORE INTO Quiz (id,topicId,title,passingScore,published,isFree) SELECT 'dea-biblio-quiz-5', 'dea-biblio-group-5', 'Kuis 5. Melaporkan dan Menerbitkan', 70, 1, 0 FROM Topic WHERE id='dea-biblio-group-5';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-5-q1', 'dea-biblio-quiz-5', 'Jumlah rekaman pada tiap tahap seleksi beserta alasan pengeluarannya paling tepat disajikan pada', 'BIBLIO butir 13 dan PRIBA butir 10 meminta hasil penelusuran dan seleksi dilaporkan, lazimnya dengan diagram alir pada bagian hasil. Hanya 60% dari studi yang ditelaah Koo dan Lin melaporkannya dengan jelas.', 1 FROM Quiz WHERE id='dea-biblio-quiz-5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q1-o1', 'dea-biblio-quiz-5-q1', 'Bagian hasil dalam bentuk diagram alir', 1, 1 FROM Question WHERE id='dea-biblio-quiz-5-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q1-o2', 'dea-biblio-quiz-5-q1', 'Pendahuluan dalam bentuk paragraf', 0, 2 FROM Question WHERE id='dea-biblio-quiz-5-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q1-o3', 'dea-biblio-quiz-5-q1', 'Diskusi sebagai keterbatasan', 0, 3 FROM Question WHERE id='dea-biblio-quiz-5-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q1-o4', 'dea-biblio-quiz-5-q1', 'Ucapan terima kasih', 0, 4 FROM Question WHERE id='dea-biblio-quiz-5-q1';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q1-o5', 'dea-biblio-quiz-5-q1', 'Judul naskah', 0, 5 FROM Question WHERE id='dea-biblio-quiz-5-q1';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-5-q2', 'dea-biblio-quiz-5', 'Butir PRIBA yang paling jarang dilaporkan pada 100 studi yang ditelaah Koo dan Lin, masing-masing 24%, adalah', 'Periode cakupan pada judul dan ciri basis data seperti jumlah jurnal dan rekaman saat penelusuran masing-masing hanya dilaporkan oleh 24% studi. Pernyataan ketersediaan data dilaporkan oleh 28% studi.', 2 FROM Quiz WHERE id='dea-biblio-quiz-5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q2-o1', 'dea-biblio-quiz-5-q2', 'Tujuan pada abstrak dan alasan penelitian', 0, 1 FROM Question WHERE id='dea-biblio-quiz-5-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q2-o2', 'dea-biblio-quiz-5-q2', 'Periode cakupan pada judul dan ciri basis data', 1, 2 FROM Question WHERE id='dea-biblio-quiz-5-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q2-o3', 'dea-biblio-quiz-5-q2', 'Strategi penelusuran dan indikator bibliometrik', 0, 3 FROM Question WHERE id='dea-biblio-quiz-5-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q2-o4', 'dea-biblio-quiz-5-q2', 'Perangkat lunak dan keterbatasan', 0, 4 FROM Question WHERE id='dea-biblio-quiz-5-q2';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q2-o5', 'dea-biblio-quiz-5-q2', 'Konflik kepentingan dan sumber dana', 0, 5 FROM Question WHERE id='dea-biblio-quiz-5-q2';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-5-q3', 'dea-biblio-quiz-5', 'Hal yang membedakan susunan naskah bibliometrik dari naskah penelitian empiris menurut Öztürk dkk. adalah', 'Analisis bibliometrik sendiri adalah alat untuk menelaah pustaka dan pustaka yang ditelaah menjadi sampel penelitian. Karena itu naskahnya lazim terdiri atas pendahuluan, metode, hasil, dan diskusi tanpa bagian tinjauan pustaka tersendiri.', 3 FROM Quiz WHERE id='dea-biblio-quiz-5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q3-o1', 'dea-biblio-quiz-5-q3', 'Tidak memiliki bagian metode', 0, 1 FROM Question WHERE id='dea-biblio-quiz-5-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q3-o2', 'dea-biblio-quiz-5-q3', 'Tidak memiliki diskusi', 0, 2 FROM Question WHERE id='dea-biblio-quiz-5-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q3-o3', 'dea-biblio-quiz-5-q3', 'Tidak memerlukan bagian tinjauan pustaka tersendiri karena pustaka yang ditelaah sekaligus menjadi sampel', 1, 3 FROM Question WHERE id='dea-biblio-quiz-5-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q3-o4', 'dea-biblio-quiz-5-q3', 'Tidak memerlukan abstrak', 0, 4 FROM Question WHERE id='dea-biblio-quiz-5-q3';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q3-o5', 'dea-biblio-quiz-5-q3', 'Tidak memerlukan daftar pustaka', 0, 5 FROM Question WHERE id='dea-biblio-quiz-5-q3';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-5-q4', 'dea-biblio-quiz-5', 'Kalimat yang paling tepat untuk menyatakan pedoman pelaporan pada metode adalah', 'Pedoman pelaporan yang sesuai untuk studi bibliometrik adalah BIBLIO atau usulan PRIBA. Diagram alir PRISMA 2020 dapat dipinjam untuk menyajikan seleksi rekaman. Menyatakan studi mengikuti PRISMA tidak tepat karena sebagian besar butirnya tidak berlaku.', 4 FROM Quiz WHERE id='dea-biblio-quiz-5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q4-o1', 'dea-biblio-quiz-5-q4', 'Studi ini dilakukan sesuai PRISMA 2020', 0, 1 FROM Question WHERE id='dea-biblio-quiz-5-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q4-o2', 'dea-biblio-quiz-5-q4', 'Studi ini tidak memerlukan pedoman pelaporan', 0, 2 FROM Question WHERE id='dea-biblio-quiz-5-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q4-o3', 'dea-biblio-quiz-5-q4', 'Studi ini mengikuti CONSORT', 0, 3 FROM Question WHERE id='dea-biblio-quiz-5-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q4-o4', 'dea-biblio-quiz-5-q4', 'Naskah dilaporkan mengikuti daftar periksa BIBLIO dan diagram alir meminjam bentuk PRISMA 2020', 1, 4 FROM Question WHERE id='dea-biblio-quiz-5-q4';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q4-o5', 'dea-biblio-quiz-5-q4', 'Studi ini mengikuti pedoman VOSviewer', 0, 5 FROM Question WHERE id='dea-biblio-quiz-5-q4';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-5-q5', 'dea-biblio-quiz-5', 'Menurut Öztürk dkk. salah satu jenis naskah bibliometrik yang bermasalah adalah naskah yang', 'Tiga jenis naskah yang bermasalah adalah yang sebenarnya tinjauan naratif, yang hanya memberi gambaran umum, dan yang menjalankan teknik secara teknis tanpa menilai dan menafsirkan peta. Melaporkan string, menyebut keterbatasan, dan melibatkan ahli klinis adalah praktik yang baik.', 5 FROM Quiz WHERE id='dea-biblio-quiz-5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q5-o1', 'dea-biblio-quiz-5-q5', 'Memakai lebih dari satu teknik pemetaan', 0, 1 FROM Question WHERE id='dea-biblio-quiz-5-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q5-o2', 'dea-biblio-quiz-5-q5', 'Menyebut keterbatasan pada diskusi', 0, 2 FROM Question WHERE id='dea-biblio-quiz-5-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q5-o3', 'dea-biblio-quiz-5-q5', 'Melaporkan string pencarian secara lengkap', 0, 3 FROM Question WHERE id='dea-biblio-quiz-5-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q5-o4', 'dea-biblio-quiz-5-q5', 'Melibatkan ahli klinis dalam menafsirkan klaster', 0, 4 FROM Question WHERE id='dea-biblio-quiz-5-q5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q5-o5', 'dea-biblio-quiz-5-q5', 'Menjalankan teknik secara teknis saja tanpa menilai, membahas, atau menafsirkan peta yang dihasilkan', 1, 5 FROM Question WHERE id='dea-biblio-quiz-5-q5';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-5-q6', 'dea-biblio-quiz-5', 'Prinsip pertama Leiden Manifesto menyatakan bahwa', 'Leiden Manifesto menempatkan angka sebagai pendukung penilaian kualitatif oleh ahli dan bukan penggantinya. Prinsip lain meminta proses yang terbuka, kesempatan bagi pihak yang dinilai untuk memeriksa data, dan penilaian perorangan yang didasarkan pada portofolio.', 6 FROM Quiz WHERE id='dea-biblio-quiz-5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q6-o1', 'dea-biblio-quiz-5-q6', 'Penilaian kuantitatif mendukung penilaian kualitatif oleh ahli', 1, 1 FROM Question WHERE id='dea-biblio-quiz-5-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q6-o2', 'dea-biblio-quiz-5-q6', 'Indikator kuantitatif menggantikan penilaian ahli', 0, 2 FROM Question WHERE id='dea-biblio-quiz-5-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q6-o3', 'dea-biblio-quiz-5-q6', 'Peneliti dinilai hanya dari indeks h', 0, 3 FROM Question WHERE id='dea-biblio-quiz-5-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q6-o4', 'dea-biblio-quiz-5-q6', 'Jurnal dinilai hanya dari Impact Factor', 0, 4 FROM Question WHERE id='dea-biblio-quiz-5-q6';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q6-o5', 'dea-biblio-quiz-5-q6', 'Data penilaian dirahasiakan dari pihak yang dinilai', 0, 5 FROM Question WHERE id='dea-biblio-quiz-5-q6';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-5-q7', 'dea-biblio-quiz-5', 'Kata yang paling tepat untuk menyebut negara dengan jumlah terbitan terbanyak dalam naskah bibliometrik adalah', 'Jumlah terbitan menunjukkan produktivitas dan bukan mutu. Peringkat bergantung pada basis data, periode, dan cara penghitungan. Naskah sebaiknya memakai kata paling produktif atau paling banyak disitasi dan menyertakan angka mentahnya.', 7 FROM Quiz WHERE id='dea-biblio-quiz-5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q7-o1', 'dea-biblio-quiz-5-q7', 'Negara terbaik', 0, 1 FROM Question WHERE id='dea-biblio-quiz-5-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q7-o2', 'dea-biblio-quiz-5-q7', 'Negara paling produktif menurut basis data dan periode yang dipakai', 1, 2 FROM Question WHERE id='dea-biblio-quiz-5-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q7-o3', 'dea-biblio-quiz-5-q7', 'Negara dengan penelitian paling bermutu', 0, 3 FROM Question WHERE id='dea-biblio-quiz-5-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q7-o4', 'dea-biblio-quiz-5-q7', 'Negara paling maju di bidang itu', 0, 4 FROM Question WHERE id='dea-biblio-quiz-5-q7';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q7-o5', 'dea-biblio-quiz-5-q7', 'Negara dengan dokter paling ahli', 0, 5 FROM Question WHERE id='dea-biblio-quiz-5-q7';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-5-q8', 'dea-biblio-quiz-5', 'Menurut ICMJE perangkat kecerdasan buatan yang dipakai saat menyusun naskah', 'ICMJE menyatakan perangkat kecerdasan buatan tidak dapat dicantumkan sebagai penulis karena tidak dapat bertanggung jawab atas ketepatan, integritas, dan keaslian karya. Penulis mengungkapkan pemakaiannya dan tetap bertanggung jawab penuh atas isi naskah.', 8 FROM Quiz WHERE id='dea-biblio-quiz-5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q8-o1', 'dea-biblio-quiz-5-q8', 'Dapat dicantumkan sebagai penulis terakhir', 0, 1 FROM Question WHERE id='dea-biblio-quiz-5-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q8-o2', 'dea-biblio-quiz-5-q8', 'Tidak perlu disebut bila hanya menyunting bahasa', 0, 2 FROM Question WHERE id='dea-biblio-quiz-5-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q8-o3', 'dea-biblio-quiz-5-q8', 'Tidak dapat menjadi penulis dan pemakaiannya harus diungkapkan', 1, 3 FROM Question WHERE id='dea-biblio-quiz-5-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q8-o4', 'dea-biblio-quiz-5-q8', 'Bertanggung jawab atas ketepatan rujukan', 0, 4 FROM Question WHERE id='dea-biblio-quiz-5-q8';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q8-o5', 'dea-biblio-quiz-5-q8', 'Dapat menggantikan salah satu kriteria penulis', 0, 5 FROM Question WHERE id='dea-biblio-quiz-5-q8';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-5-q9', 'dea-biblio-quiz-5', 'Bahan yang paling umum dapat dibagikan untuk memenuhi pernyataan ketersediaan data pada studi bibliometrik adalah', 'String pencarian, tanggal penelusuran, daftar PMID atau DOI, berkas tesaurus, dan berkas peta atau skrip analisis dapat dilampirkan sebagai bahan tambahan. Berkas ekspor lengkap dari basis data berlangganan belum tentu boleh dibagikan sehingga ketentuan lisensinya perlu diperiksa.', 9 FROM Quiz WHERE id='dea-biblio-quiz-5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q9-o1', 'dea-biblio-quiz-5-q9', 'Rekam medis pasien', 0, 1 FROM Question WHERE id='dea-biblio-quiz-5-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q9-o2', 'dea-biblio-quiz-5-q9', 'Kata sandi akun basis data berlangganan', 0, 2 FROM Question WHERE id='dea-biblio-quiz-5-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q9-o3', 'dea-biblio-quiz-5-q9', 'Naskah lengkap semua artikel yang dianalisis', 0, 3 FROM Question WHERE id='dea-biblio-quiz-5-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q9-o4', 'dea-biblio-quiz-5-q9', 'String pencarian, daftar pengenal rekaman, dan berkas tesaurus', 1, 4 FROM Question WHERE id='dea-biblio-quiz-5-q9';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q9-o5', 'dea-biblio-quiz-5-q9', 'Formulir persetujuan subjek', 0, 5 FROM Question WHERE id='dea-biblio-quiz-5-q9';
INSERT OR IGNORE INTO Question (id,quizId,text,explanation,"order") SELECT 'dea-biblio-quiz-5-q10', 'dea-biblio-quiz-5', 'Pada contoh naskah tentang kecerdasan buatan pada tuberkulosis, keterbatasan yang paling khas akibat pemakaian PubMed saja adalah', 'Banyak penelitian kecerdasan buatan terbit pada jurnal teknik dan prosiding konferensi ilmu komputer yang tidak terindeks di PubMed. Pemakaian satu basis data biomedis karena itu membuat sebagian pustaka tidak terhitung dan hal ini ditulis sebagai keterbatasan.', 10 FROM Quiz WHERE id='dea-biblio-quiz-5';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q10-o1', 'dea-biblio-quiz-5-q10', 'Jumlah rekaman terlalu sedikit untuk dianalisis', 0, 1 FROM Question WHERE id='dea-biblio-quiz-5-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q10-o2', 'dea-biblio-quiz-5-q10', 'PubMed tidak memuat kata kunci penulis', 0, 2 FROM Question WHERE id='dea-biblio-quiz-5-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q10-o3', 'dea-biblio-quiz-5-q10', 'PubMed tidak memuat nama jurnal', 0, 3 FROM Question WHERE id='dea-biblio-quiz-5-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q10-o4', 'dea-biblio-quiz-5-q10', 'PubMed hanya memuat artikel berbahasa Indonesia', 0, 4 FROM Question WHERE id='dea-biblio-quiz-5-q10';
INSERT OR IGNORE INTO QuestionOption (id,questionId,text,isCorrect,"order") SELECT 'dea-biblio-quiz-5-q10-o5', 'dea-biblio-quiz-5-q10', 'Terbitan pada jurnal teknik dan prosiding ilmu komputer yang tidak terindeks di PubMed tidak terhitung', 1, 5 FROM Question WHERE id='dea-biblio-quiz-5-q10';
